import{c as r,Q as o,j as n,m as e}from"./chunks/framework.rWdQudnF.js";const _=JSON.parse('{"title":"基于构件的软件工程","description":"","frontmatter":{"title":"基于构件的软件工程"},"headers":[],"relativePath":"综合知识/软件工程/基于构件的软件工程.md","filePath":"综合知识/软件工程/基于构件的软件工程.md","lastUpdated":null}'),s={name:"综合知识/软件工程/基于构件的软件工程.md"};function a(d,t,l,g,p,i){return o(),n("div",null,[...t[0]||(t[0]=[e('<hr><h3 id="基于构件的软件工程-cbse" tabindex="-1">基于构件的软件工程（CBSE） <a class="header-anchor" href="#基于构件的软件工程-cbse" aria-label="Permalink to &quot;基于构件的软件工程（CBSE）&quot;">​</a></h3><blockquote><p>核心理念：<strong>&quot;购买而不是重新构造&quot;</strong>，将开发重点从编写新代码转移到基于已有构件的组装。</p></blockquote><p><strong>CBSE 过程：</strong></p><ol><li>系统需求概览 → 2. 识别候选构件 → 3. 根据构件修改需求 → 4. 体系结构设计 → 5. 构件定制与适配 → 6. 组装构件创建系统</li></ol><p><strong>CBS 与传统过程的不同点：</strong></p><table tabindex="0"><thead><tr><th>不同点</th><th>说明</th></tr></thead><tbody><tr><td><strong>早期需要完整需求</strong></td><td>便于尽可能多地识别可复用构件</td></tr><tr><td><strong>根据构件细化需求</strong></td><td>如果可用构件不满足需求，考虑由复用构件支持的相关需求</td></tr><tr><td><strong>设计完成后进一步搜索构件</strong></td><td>在系统体系结构设计完成后，<strong>进一步搜索和设计精化构件</strong></td></tr><tr><td><strong>开发即组装</strong></td><td>开发过程就是将找到的构件集成在一起</td></tr></tbody></table><h3 id="构件特征与组装" tabindex="-1">构件特征与组装 <a class="header-anchor" href="#构件特征与组装" aria-label="Permalink to &quot;构件特征与组装&quot;">​</a></h3><p><strong>构件五大特征：</strong> 可组装性（公开接口）、可部署性（自包含）、文档化、独立性、标准化。</p><p><strong>构件模型三要素：</strong> 接口、使用信息（全局唯一标识符）、部署。</p><h3 id="构建组装" tabindex="-1">构建组装 <a class="header-anchor" href="#构建组装" aria-label="Permalink to &quot;构建组装&quot;">​</a></h3><p><strong>三种组装方式：</strong> 顺序组装、层次组装、叠加组装。</p><table tabindex="0"><thead><tr><th style="text-align:left;">组装方式</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>顺序组装</strong></td><td>数据依次流经一系列构件处理</td><td>清晰的<strong>线性管道</strong>处理过程</td></tr><tr><td style="text-align:left;"><strong>层次组装</strong></td><td>下层为上层提供服务</td><td>分层架构</td></tr><tr><td style="text-align:left;"><strong>叠加组装</strong></td><td>合并两个或多个现有构件功能，形成新接口</td><td>需要合并现有构件功能</td></tr></tbody></table><p><strong>三类不兼容问题：</strong> 参数不兼容、操作不兼容、操作不完备 → 编写<strong>适配器</strong>解决。</p><blockquote><p>⚠️ 常见坑：「用户界面不兼容」不属于构件组装的三类接口不兼容问题。</p></blockquote><p><strong>CBSD 的 5 个主要阶段（不含代码编写）★：</strong></p><ol><li>需求分析和定义 → 2. 架构设计 → 3. 构件库的建立 → 4. 应用软件构建 → 5. 测试和发布</li></ol><blockquote><p>🎯 一句话结论：CBSD <strong>不含单独的&quot;代码编写&quot;阶段</strong>，开发过程就是构件组装过程。CBSD 融合了<strong>螺旋模型</strong>的特征，本质上是<strong>演化型</strong>的。</p></blockquote><p><strong>构件获取4途径：</strong> ①从现有构件中获取 ②通过遗留工程提取 ③购买 COTS ④自行开发新构件</p><p><strong>构件库检索3方法：</strong> ①基于关键字 ②刻面检索 ③超文本检索</p><hr>',21)])])}const c=r(s,[["render",a]]);export{_ as __pageData,c as default};
